import "./TrailerModal.scss";
import ReactDOM from "react-dom";
import { useState, useEffect } from 'react';
import { connect } from 'react-redux';
import axios from "axios";

const TrailerModal = ({onModalClick, movie}) => {
    const [ytVideo, setYtVideo] = useState("");
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    useEffect(()=>{
        const asyncFunction = async ()=>{
            try {
                const {data: videosList} = await axios.get(`https://api.themoviedb.org/3/movie/${movie.imdb_id}/videos`, {params: {
                    api_key: "e6ed4845cf8d5e5ce279a43667893d79"
                }});

                let trailers = videosList.results.filter(video => video.type === "Trailer");
                setYtVideo(trailers[trailers.length-1]);
            } catch (err) {
                setError("Failed to load trailer.");
            } finally {
                setLoading(false);
            }
        }

        asyncFunction();
    },[]);

    const renderContent = () => {
        if (loading) return <h1>Loading ...</h1>;
        if (error) return <h1 onClick={onModalClick}>{error} Click here to exit.</h1>;
        if (ytVideo?.key) return (
            <iframe
                id="frame"
                src={`https://www.youtube.com/embed/${ytVideo.key}?autoplay=1`}
                frameBorder="0"
                width="100%"
                height="100%"
                allowFullScreen
                title={ytVideo.name}
            />
        );
        return <h1 onClick={onModalClick}>Trailer unavailable, click here to exit.</h1>;
    }

    return ReactDOM.createPortal(
        <div className="modal-list">
            <div className="modal-list-content-trailer">
                {renderContent()}
            </div>
            <div className="modal-list-exit" onClick={onModalClick}></div>
        </div>,
        document.querySelector("#modal-trailer")
    );
}

export default connect(null)(TrailerModal);
